function keptInOrder(s: string, t: string): boolean {
  const where = new Map<string, number[]>();
  for (let j = 0; j < t.length; j++) {
    if (!where.has(t[j])) where.set(t[j], []);
    where.get(t[j])!.push(j);
  }
  let pos = -1; // index in t of the last match
  for (const ch of s) {
    const list = where.get(ch);
    if (!list) return false;
    let lo = 0, hi = list.length; // first entry > pos
    while (lo < hi) {
      const mid = (lo + hi) >> 1;
      if (list[mid] <= pos) lo = mid + 1; else hi = mid;
    }
    if (lo === list.length) return false;
    pos = list[lo];
  }
  return true;
}

